probes.source:
outcome("list-add") {
	val l = mutableListOf(1, 2, 3)
	for (x in l) if (x == 1) l.add(4)
	l
}
outcome("list-remove-first") {
	val l = mutableListOf(1, 2, 3)
	for (x in l) if (x == 1) l.remove(1)
	l
}
outcome("list-remove-second") {
	val l = mutableListOf(1, 2, 3)
	for (x in l) if (x == 2) l.remove(2)
	l
}
outcome("list-remove-last") {
	val l = mutableListOf(1, 2, 3)
	for (x in l) if (x == 3) l.remove(3)
	l
}
outcome("map-put") {
	val m = mutableMapOf(1 to 1, 2 to 2)
	for (k in m.keys) if (k < 10) m[k + 10] = 0
	m
}
outcome("hashmap-remove-other") {
	val m = hashMapOf(1 to 1, 2 to 2, 3 to 3)
	for (k in m.keys) if (k == 1) m.remove(2)
	m
}
outcome("set-add") {
	val s = linkedSetOf(1, 2)
	for (x in s) if (x < 10) s.add(x + 10)
	s
}
outcome("sublist-after-add") {
	val l = mutableListOf(1, 2, 3)
	val s = l.subList(0, 2)
	l.add(4)
	s.toList()
}
outcome("sublist-size-after-add") {
	val l = mutableListOf(1, 2, 3)
	val s = l.subList(0, 2)
	l.add(4)
	s.size
}
outcome("next-on-empty") { emptyList<Int>().iterator().next() }
outcome("remove-before-next") { mutableListOf(1).iterator().remove() }
outcome("set-before-next") { mutableListOf(1).listIterator().set(2) }
outcome("removeAt-range") { mutableListOf(1).removeAt(1) }
outcome("subList-range") { listOf(1, 2).subList(1, 5) }

val zero = "0".toInt()
failure("toInt") { "x".toInt() }
failure("toInt-empty") { "".toInt() }
failure("toLong") { "9999999999999999999".toLong() }
failure("toDouble") { "x".toDouble() }
failure("toUInt") { "-1".toUInt() }
failure("toUByte") { "256".toUByte() }
failure("int-div-zero") { 1 / zero }
failure("long-div-zero") { 1L / zero }
failure("int-mod-zero") { 1 % zero }
failure("floorDiv-zero") { 1.floorDiv(zero) }
failure("list-index") { listOf(1)[3] }
failure("array-index") { arrayOf(1)[5] }
failure("string-index") { "abc"[10] }
failure("substring") { "abc".substring(5) }
failure("substring-range") { "abc".substring(2, 1) }
failure("subList") { listOf(1, 2).subList(1, 5) }
failure("removeAt") { mutableListOf(1).removeAt(1) }
failure("negative-array") { IntArray(zero - 1) }
failure("negative-list") { List(zero - 1) { 0 } }
failure("first-empty") { emptyList<Int>().first() }
failure("last-empty") { emptyList<Int>().last() }
failure("single-many") { listOf(1, 2).single() }
failure("removeFirst-empty") { mutableListOf<Int>().removeFirst() }
failure("require") { require(false) }
failure("require-message") { require(false) { "custom" } }
failure("check") { check(false) }
failure("error") { error("boom") }
failure("checkNotNull") { checkNotNull(null as Int?) }
failure("not-null-assert") { (null as String?)!! }
failure("todo") { TODO() }
failure("todo-message") { TODO("later") }
failure("cast") { (1 as Any) as String }
failure("null-cast") { (null as Any?) as String }
failure("getValue") { emptyMap<Int, Int>().getValue(1) }
failure("repeat-negative") { "a".repeat(zero - 1) }
failure("chunked-zero") { listOf(1).chunked(zero) }
failure("step-zero") { 1..3 step zero }
failure("random-empty") { Random(1).nextInt(5, 5) }
failure("radix") { 255.toString(37) }
failure("lateinit") { Holder().name }
failure("iterator-end") { listOf(1).iterator().apply { next() }.next() }

for ((name, d) in listOf(
	"0.5" to 0.5, "1.5" to 1.5, "2.5" to 2.5, "-0.5" to -0.5, "-1.5" to -1.5,
	"-2.5" to -2.5, "0.49999999999999994" to 0.49999999999999994,
	"2.4999999999999996" to 2.4999999999999996,
	"4503599627370497" to 4503599627370497.0,
)) {
	val r = round(d)
	line(name, "round=" + r + " int=" + d.roundToInt() + " long=" + d.roundToLong())
}
outcome("roundToInt-nan") { Double.NaN.roundToInt() }
line("roundToInt-1e10", 1e10.roundToInt())
line("roundToInt-int-max-half", 2147483647.5.roundToInt())
line("float-0.5", 0.5f.roundToInt())
line("float-2.5", 2.5f.roundToInt())
line("float-neg-2.5", (-2.5f).roundToInt())
line("float-8388609", 8388609f.roundToInt())
